<?php
define('APP_INIT', true);
require_once __DIR__.'/../config/app.php';
require_once ROOT_PATH.'/includes/auth_check.php';
require_once ROOT_PATH.'/includes/platform_check.php';
requirePlatformAdmin();
$db=Database::getConnection();
$plans=$db->query("SELECT * FROM subscription_plans ORDER BY display_order,id")->fetchAll();
$activePlans=array_values(array_filter($plans,fn($plan)=>$plan['status']==='active'));
$tenants=$db->query("SELECT t.id,t.name,t.slug,t.owner_name,t.owner_email,p.name plan_name,s.plan_id,s.status,s.ends_at FROM tenants t LEFT JOIN tenant_subscriptions s ON s.id=(SELECT id FROM tenant_subscriptions x WHERE x.tenant_id=t.id ORDER BY id DESC LIMIT 1) LEFT JOIN subscription_plans p ON p.id=s.plan_id ORDER BY t.id DESC")->fetchAll();
$payments=$db->query("SELECT sp.id,sp.amount,sp.billing_period,sp.payment_method,sp.transaction_reference,sp.attachment_path,sp.payment_date,t.name tenant_name,p.name plan_name FROM subscription_payments sp JOIN tenants t ON t.id=sp.tenant_id LEFT JOIN tenant_subscriptions s ON s.id=sp.subscription_id LEFT JOIN subscription_plans p ON p.id=s.plan_id WHERE sp.status='pending' ORDER BY sp.id DESC")->fetchAll();
$registeredUsers=$db->query("SELECT u.name,u.username,u.email,u.phone,u.status,u.created_at,t.name tenant_name,r.name role_name FROM users u JOIN tenants t ON t.id=u.tenant_id LEFT JOIN roles r ON r.id=u.role_id WHERE COALESCE(u.is_platform_admin,0)=0 ORDER BY u.id DESC LIMIT 100")->fetchAll();
$csrf=getCsrfToken();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Platform management</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#060914;color:#f3f4fa}.navy{background:#0e1425}.card{background:linear-gradient(145deg,#151a2c,#0d1120);border:1px solid #303657;color:#edf0ff;border-radius:17px}.muted{color:#adb3c9}.violet{background:linear-gradient(90deg,#6d28d9,#a855f7);border:0}.table{--bs-table-bg:transparent;--bs-table-color:#e9edff;--bs-table-border-color:#2a304a}.form-control,.form-select{background:#0a0e1b;color:#fff;border-color:#414a6f}.form-control:focus,.form-select:focus{background:#0a0e1b;color:#fff}.form-select option{background:#0a0e1b}</style></head><body>
<nav class="navbar navbar-dark navy border-bottom border-secondary-subtle px-3 px-md-5"><a class="navbar-brand fw-bold" href="<?=BASE_URL?>/admin/">✦ Platform Admin</a><div><a class="btn btn-outline-light btn-sm me-2" href="<?=BASE_URL?>/admin/">Dashboard</a><a class="btn btn-sm violet text-white" href="<?=BASE_URL?>/logout.php">Logout</a></div></nav>
<main class="container py-5"><div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><div><p class="text-uppercase small text-info mb-1">SaaS operations</p><h1 class="h2">Tenants, plans & payments</h1><p class="muted mb-0">Platform-only controls. Every action is checked on the server.</p></div><div><a class="btn btn-outline-light" href="#new-tenant">Add tenant</a> <a class="btn violet text-white" href="#new-plan">Create plan</a></div></div><div id="notice" aria-live="polite"></div>
<section id="new-tenant" class="card p-4 mb-4"><h2 class="h5">Create tenant workspace</h2><p class="muted small">Creates an isolated business, its first administrator, and a trial subscription.</p><form id="tenantForm" class="row g-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="col-md-4"><label class="form-label">Business name</label><input name="name" required class="form-control"></div><div class="col-md-4"><label class="form-label">Owner name</label><input name="owner_name" required class="form-control"></div><div class="col-md-4"><label class="form-label">Owner email</label><input name="owner_email" type="email" required class="form-control"></div><div class="col-md-4"><label class="form-label">Mobile</label><input name="owner_phone" class="form-control"></div><div class="col-md-4"><label class="form-label">Administrator username</label><input name="username" required class="form-control"></div><div class="col-md-4"><label class="form-label">Temporary password</label><input name="password" type="password" minlength="8" required class="form-control"></div><div class="col-md-4"><label class="form-label">Starting plan</label><select name="plan_id" required class="form-select"><?php foreach($activePlans as $plan):?><option value="<?=$plan['id']?>"><?=htmlspecialchars($plan['name'])?></option><?php endforeach?></select></div><div class="col-12"><button class="btn violet text-white">Create isolated tenant</button></div></form></section>
<section class="card p-4 mb-4"><h2 class="h5">Registered businesses <span class="muted fs-6">(<?=count($tenants)?>)</span></h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Business</th><th>Plan</th><th>Subscription</th><th>Expiry</th><th>Workspace</th><th>Control</th></tr></thead><tbody><?php foreach($tenants as $t):?><tr><td><strong><?=htmlspecialchars($t['name'])?></strong><div class="small muted"><?=htmlspecialchars($t['owner_email']??'')?></div></td><td><?=htmlspecialchars($t['plan_name']??'—')?></td><td><?=htmlspecialchars($t['status']??'—')?></td><td><?=htmlspecialchars($t['ends_at']??'—')?></td><td><code><?=htmlspecialchars($t['slug'])?></code></td><td><button class="btn btn-outline-light btn-sm subscription" data-tenant="<?=$t['id']?>" data-plan="<?=$t['plan_id']?>" data-status="<?=htmlspecialchars($t['status']??'active')?>">Change access</button></td></tr><?php endforeach?></tbody></table></div></section>
<section class="card p-4 mb-4"><h2 class="h5">Registered tenant users</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>User</th><th>Business</th><th>Contact</th><th>Role</th><th>Status</th><th>Registered</th></tr></thead><tbody><?php foreach($registeredUsers as $user):?><tr><td><strong><?=htmlspecialchars($user['name'])?></strong><div class="small muted">@<?=htmlspecialchars($user['username'])?></div></td><td><?=htmlspecialchars($user['tenant_name'])?></td><td><?=htmlspecialchars($user['email']??'—')?><div class="small muted"><?=htmlspecialchars($user['phone']??'')?></div></td><td><?=htmlspecialchars($user['role_name']??'—')?></td><td><?=htmlspecialchars($user['status'])?></td><td><?=htmlspecialchars($user['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section id="payments" class="card p-4 mb-4"><h2 class="h5">Pending payment review</h2><?php if(!$payments):?><p class="muted mb-0">No payments are waiting for review.</p><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Business</th><th>Plan / cycle</th><th>Method / date</th><th>Amount</th><th>Reference & proof</th><th>Action</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=htmlspecialchars($p['tenant_name'])?></td><td><?=htmlspecialchars($p['plan_name']??'—')?> / <?=htmlspecialchars($p['billing_period'])?></td><td><?=htmlspecialchars($p['payment_method'])?><div class="small muted"><?=htmlspecialchars($p['payment_date'])?></div></td><td>৳<?=number_format((float)$p['amount'],2)?></td><td><?=htmlspecialchars($p['transaction_reference']??'—')?><?php if(!empty($p['attachment_path'])):?><div><a class="link-info small" target="_blank" href="<?=BASE_URL?>/admin/payment_receipt.php?id=<?=$p['id']?>">View receipt</a></div><?php endif?></td><td><button class="btn btn-success btn-sm review" data-id="<?=$p['id']?>" data-status="approved">Approve</button> <button class="btn btn-outline-danger btn-sm review" data-id="<?=$p['id']?>" data-status="rejected">Reject</button></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<section class="card p-4 mb-4"><h2 class="h5">Current plans</h2><div class="table-responsive"><table class="table"><thead><tr><th>Plan</th><th>Monthly</th><th>Yearly</th><th>Trial</th><th>Limits</th></tr></thead><tbody><?php foreach($plans as $plan):?><tr><td><strong><?=htmlspecialchars($plan['name'])?></strong><div class="small muted"><?=htmlspecialchars($plan['code'])?></div></td><td>৳<?=number_format((float)$plan['price'],2)?></td><td>৳<?=number_format((float)$plan['yearly_price'],2)?></td><td><?=$plan['trial_days']?> days</td><td><?=($plan['company_limit']??'∞')?> / <?=($plan['product_limit']??'∞')?> / <?=($plan['customer_limit']??'∞')?> / <?=($plan['user_limit']??'∞')?></td></tr><?php endforeach?></tbody></table></div></section>
<section id="new-plan" class="card p-4"><h2 class="h5">Create subscription plan</h2><p class="muted small">Prices and usage limits are platform configuration—not hard-coded in customer screens.</p><form id="planForm" class="row g-3"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="col-md-3"><label class="form-label">Code</label><input name="code" class="form-control" placeholder="GROWTH" required></div><div class="col-md-3"><label class="form-label">Name</label><input name="name" class="form-control" placeholder="Growth" required></div><div class="col-md-2"><label class="form-label">Monthly ৳</label><input name="price" type="number" min="0" step=".01" class="form-control" required></div><div class="col-md-2"><label class="form-label">Yearly ৳</label><input name="yearly_price" type="number" min="0" step=".01" class="form-control" required></div><div class="col-md-2"><label class="form-label">Trial days</label><input name="trial_days" type="number" min="0" value="14" class="form-control"></div><div class="col-md-3"><label class="form-label">Companies</label><input name="company_limit" type="number" min="0" class="form-control" placeholder="Blank = unlimited"></div><div class="col-md-3"><label class="form-label">Products</label><input name="product_limit" type="number" min="0" class="form-control" placeholder="Blank = unlimited"></div><div class="col-md-3"><label class="form-label">Customers</label><input name="customer_limit" type="number" min="0" class="form-control" placeholder="Blank = unlimited"></div><div class="col-md-3"><label class="form-label">Users</label><input name="user_limit" type="number" min="0" class="form-control" placeholder="Blank = unlimited"></div><input type="hidden" name="status" value="active"><div><button class="btn violet text-white">Save plan</button></div></form></section></main>
<script>const csrf=<?=json_encode($csrf)?>,notice=document.querySelector('#notice'),plans=<?=json_encode(array_map(fn($p)=>['id'=>(int)$p['id'],'name'=>$p['name']],$activePlans))?>;function show(ok,msg){notice.innerHTML='<div class="alert '+(ok?'alert-success':'alert-danger')+'">'+msg+'</div>';window.scrollTo({top:0,behavior:'smooth'})}async function post(url,data){const r=await fetch(url,{method:'POST',body:data});return r.json()}document.querySelector('#tenantForm').onsubmit=async e=>{e.preventDefault();let x=await post('<?=BASE_URL?>/ajax/platform/create_tenant.php',new FormData(e.target));show(x.success,x.message);if(x.success)setTimeout(()=>location.reload(),650)};document.querySelector('#planForm').onsubmit=async e=>{e.preventDefault();let x=await post('<?=BASE_URL?>/ajax/platform/save_plan.php',new FormData(e.target));show(x.success,x.message);if(x.success)setTimeout(()=>location.reload(),650)};document.querySelectorAll('.review').forEach(b=>b.onclick=async()=>{let f=new FormData();f.append('csrf_token',csrf);f.append('id',b.dataset.id);f.append('status',b.dataset.status);let x=await post('<?=BASE_URL?>/ajax/platform/review_payment.php',f);show(x.success,x.message);if(x.success)setTimeout(()=>location.reload(),650)});document.querySelectorAll('.subscription').forEach(b=>b.onclick=async()=>{let options=plans.map(p=>p.id+': '+p.name).join('\n'),plan=prompt('Plan ID:\n'+options,b.dataset.plan),status=prompt('Status: trial, active, grace_period, expired, suspended, cancelled',b.dataset.status);if(!plan||!status)return;let f=new FormData();f.append('csrf_token',csrf);f.append('tenant_id',b.dataset.tenant);f.append('plan_id',plan);f.append('status',status);f.append('ends_at','');let x=await post('<?=BASE_URL?>/ajax/platform/update_subscription.php',f);show(x.success,x.message);if(x.success)setTimeout(()=>location.reload(),650)});</script></body></html>
